import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Perguntas frequentes","description":"","frontmatter":{"title":"Perguntas frequentes"},"headers":[],"relativePath":"perguntas-frequentes.md","filePath":"perguntas-frequentes.md"}'),n={name:"perguntas-frequentes.md"};function u(i,a,t,d,l,c){return o(),r("div",null,a[0]||(a[0]=[s('<h1 id="perguntas-frequentes" tabindex="-1">Perguntas frequentes <a class="header-anchor" href="#perguntas-frequentes" aria-label="Permalink to &quot;Perguntas frequentes&quot;">​</a></h1><h2 id="instalacao-e-uso" tabindex="-1">Instalação e uso <a class="header-anchor" href="#instalacao-e-uso" aria-label="Permalink to &quot;Instalação e uso&quot;">​</a></h2><h3 id="instalei-mas-nada-mudou-no-eproc-por-que" tabindex="-1">Instalei, mas nada mudou no eproc. Por quê? <a class="header-anchor" href="#instalei-mas-nada-mudou-no-eproc-por-que" aria-label="Permalink to &quot;Instalei, mas nada mudou no eproc. Por quê?&quot;">​</a></h3><p>Depois da instalação, o eploc fica <strong>desativado</strong> até você aceitar os termos de uso na página de configurações (aba <strong>Sobre</strong>). Veja o <a href="./inicio-rapido#_3-ativar-a-extensao">Início rápido</a>. Se já aceitou, confira no <a href="./geral/popup">popup</a> se o interruptor geral está em &quot;Extensão ativa&quot; e se a funcionalidade está ligada.</p><h3 id="funciona-no-edge" tabindex="-1">Funciona no Edge? <a class="header-anchor" href="#funciona-no-edge" aria-label="Permalink to &quot;Funciona no Edge?&quot;">​</a></h3><p>Sim. Instale pela mesma página da Chrome Web Store. Veja <a href="./compatibilidade">Compatibilidade</a>.</p><h3 id="funciona-no-eproc-do-meu-tribunal" tabindex="-1">Funciona no eproc do meu tribunal? <a class="header-anchor" href="#funciona-no-eproc-do-meu-tribunal" aria-label="Permalink to &quot;Funciona no eproc do meu tribunal?&quot;">​</a></h3><p>Veja a lista de endereços em <a href="./compatibilidade">Compatibilidade</a>. Se o seu tribunal não estiver lá, fale com o desenvolvedor.</p><h3 id="posso-desligar-o-que-nao-uso" tabindex="-1">Posso desligar o que não uso? <a class="header-anchor" href="#posso-desligar-o-que-nao-uso" aria-label="Permalink to &quot;Posso desligar o que não uso?&quot;">​</a></h3><p>Sim. Cada funcionalidade pode ser ligada e desligada individualmente, pelo <a href="./geral/popup">popup</a> ou pela <a href="./geral/configuracoes">página de configurações</a>. A mudança vale na hora.</p><h3 id="uma-funcionalidade-parou-de-funcionar-o-que-faco" tabindex="-1">Uma funcionalidade parou de funcionar. O que faço? <a class="header-anchor" href="#uma-funcionalidade-parou-de-funcionar-o-que-faco" aria-label="Permalink to &quot;Uma funcionalidade parou de funcionar. O que faço?&quot;">​</a></h3><p>O eproc, o SEI e o RUPE mudam sem aviso, e uma mudança de tela pode afetar o eploc. Desligue a funcionalidade pelo popup para voltar ao comportamento normal do sistema e avise pelo <a href="./contato">Contato</a>, dizendo o tribunal, a tela e o que aconteceu.</p><h3 id="o-sistema-do-tribunal-apresentou-um-erro-devo-abrir-um-chamado" tabindex="-1">O sistema do tribunal apresentou um erro. Devo abrir um chamado? <a class="header-anchor" href="#o-sistema-do-tribunal-apresentou-um-erro-devo-abrir-um-chamado" aria-label="Permalink to &quot;O sistema do tribunal apresentou um erro. Devo abrir um chamado?&quot;">​</a></h3><p>Antes de abrir um chamado no suporte do tribunal sobre uma falha no eproc, no SEI ou no RUPE:</p><ol><li>Desative o eploc pelo interruptor geral do <a href="./geral/popup">popup</a> (&quot;Extensão desativada&quot;).</li><li>Recarregue a página e tente de novo.</li><li>Se o problema continuar com o eploc desativado, ele é do sistema: abra o chamado normalmente. Se o problema sumir, ele tem relação com o eploc: fale com o desenvolvedor (veja <a href="./contato">Contato</a>), e não com o suporte do tribunal.</li></ol><p>O suporte dos tribunais cuida dos sistemas oficiais, não do eploc. Dúvidas e problemas da extensão são atendidos pelo <a href="https://eploc.com.br/reportar-problema.html" target="_blank" rel="noreferrer">formulário do site</a>, pelo grupo no WhatsApp ou por e-mail.</p><p>Se precisar enviar capturas de tela ao suporte do tribunal, prefira tirá-las com o eploc desativado. Assim a tela aparece exatamente como o suporte a conhece, o que facilita o atendimento.</p><h3 id="como-encontro-uma-configuracao" tabindex="-1">Como encontro uma configuração? <a class="header-anchor" href="#como-encontro-uma-configuracao" aria-label="Permalink to &quot;Como encontro uma configuração?&quot;">​</a></h3><p>Abra as configurações e comece a digitar: a busca procura em todas as abas, inclusive nas opções de cada funcionalidade.</p><h2 id="seguranca-e-dados" tabindex="-1">Segurança e dados <a class="header-anchor" href="#seguranca-e-dados" aria-label="Permalink to &quot;Segurança e dados&quot;">​</a></h2><h3 id="o-chrome-diz-que-o-eploc-pode-ler-e-alterar-todos-os-seus-dados-em-todos-os-sites-por-que" tabindex="-1">O Chrome diz que o eploc pode &quot;ler e alterar todos os seus dados em todos os sites&quot;. Por quê? <a class="header-anchor" href="#o-chrome-diz-que-o-eploc-pode-ler-e-alterar-todos-os-seus-dados-em-todos-os-sites-por-que" aria-label="Permalink to &quot;O Chrome diz que o eploc pode &quot;ler e alterar todos os seus dados em todos os sites&quot;. Por quê?&quot;">​</a></h3><p>É um texto genérico do navegador. O eploc só atua no eproc, SEI, RUPE e páginas do TJMG. Como cada tribunal tem um endereço próprio dentro de <code>jus.br</code>, o navegador resume a lista nessa frase. Depois de algumas atualizações, pode ser preciso clicar em &quot;Reativar&quot;. Veja <a href="./privacidade#o-aviso-ler-e-alterar-todos-os-seus-dados">Privacidade e dados</a>.</p><h3 id="o-eploc-envia-dados-de-processos-para-algum-lugar" tabindex="-1">O eploc envia dados de processos para algum lugar? <a class="header-anchor" href="#o-eploc-envia-dados-de-processos-para-algum-lugar" aria-label="Permalink to &quot;O eploc envia dados de processos para algum lugar?&quot;">​</a></h3><p>Não para o desenvolvedor. Tudo roda no seu navegador. As exceções estão descritas em <a href="./privacidade#quando-algum-dado-sai-do-navegador">Privacidade e dados</a>: o backup opcional no seu Google Drive e a consulta do Atalho PJe Mídias.</p><h3 id="o-eploc-guarda-minha-senha-do-eproc" tabindex="-1">O eploc guarda minha senha do eproc? <a class="header-anchor" href="#o-eploc-guarda-minha-senha-do-eproc" aria-label="Permalink to &quot;O eploc guarda minha senha do eproc?&quot;">​</a></h3><p>Não. O recurso <a href="./funcionalidades/eproc-login-gerenciador-senhas">Permitir credenciais salvas</a> só permite que o gerenciador de senhas do próprio navegador funcione na tela de login.</p><h3 id="o-eploc-e-oficial-do-tjmg-ou-de-algum-tribunal" tabindex="-1">O eploc é oficial do TJMG ou de algum tribunal? <a class="header-anchor" href="#o-eploc-e-oficial-do-tjmg-ou-de-algum-tribunal" aria-label="Permalink to &quot;O eploc é oficial do TJMG ou de algum tribunal?&quot;">​</a></h3><p>Não. O eploc é uma ferramenta independente, sem vínculo, endosso ou homologação de tribunais, do CNJ ou de qualquer órgão. Os atos praticados continuam sendo seus e devem ser conferidos como sempre.</p><h2 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h2><h3 id="como-levo-minhas-configuracoes-para-outro-computador" tabindex="-1">Como levo minhas configurações para outro computador? <a class="header-anchor" href="#como-levo-minhas-configuracoes-para-outro-computador" aria-label="Permalink to &quot;Como levo minhas configurações para outro computador?&quot;">​</a></h3><p>Use o <a href="./geral/backup-arquivo">backup em arquivo</a> (exportar e importar JSON) ou conecte o <a href="./geral/backup-google-drive">Google Drive</a> nos dois computadores.</p><h3 id="apaguei-um-modelo-de-mensagem-sem-querer-da-para-recuperar" tabindex="-1">Apaguei um modelo de mensagem sem querer. Dá para recuperar? <a class="header-anchor" href="#apaguei-um-modelo-de-mensagem-sem-querer-da-para-recuperar" aria-label="Permalink to &quot;Apaguei um modelo de mensagem sem querer. Dá para recuperar?&quot;">​</a></h3><p>Se o backup no Google Drive estiver ligado, use <strong>Procurar dados ausentes em backups antigos</strong>. Veja <a href="./geral/backup-google-drive#usar">Backup no Google Drive</a>.</p><h3 id="posso-passar-meus-modelos-ou-contatos-para-um-colega" tabindex="-1">Posso passar meus modelos ou contatos para um colega? <a class="header-anchor" href="#posso-passar-meus-modelos-ou-contatos-para-um-colega" aria-label="Permalink to &quot;Posso passar meus modelos ou contatos para um colega?&quot;">​</a></h3><p>Sim. Em <strong>Exportar bases de dados</strong>, exporte só os modelos ou os contatos e envie o arquivo. Veja <a href="./geral/backup-arquivo#exportar-so-algumas-bases">Backup em arquivo</a>.</p><h2 id="planos" tabindex="-1">Planos <a class="header-anchor" href="#planos" aria-label="Permalink to &quot;Planos&quot;">​</a></h2><h3 id="quanto-custa" tabindex="-1">Quanto custa? <a class="header-anchor" href="#quanto-custa" aria-label="Permalink to &quot;Quanto custa?&quot;">​</a></h3><p>As funcionalidades descritas neste manual são gratuitas e trazem o selo <strong>Gratuito</strong> na página de cada uma.</p>',38)]))}const h=e(n,[["render",u]]);export{m as __pageData,h as default};
